import{_ as s,C as a,c as o,o as l,aa as h,G as r}from"./chunks/framework.Cn7WEiMX.js";const b=JSON.parse('{"title":"注册条目","description":"","frontmatter":{"breadcrumbs":[{"title":"Continue Project","link":"/wiki"},{"title":"Terra","link":"/wiki/Terra"},{"title":"terra-api","link":"/wiki/Terra/terra-api"},{"title":"api-concepts","link":"/wiki/Terra/terra-api/api-concepts"},{"title":"注册条目","link":"/wiki/Terra/terra-api/api-concepts/registries"}]},"headers":[],"relativePath":"wiki/Terra/terra-api/api-concepts/registries.md","filePath":"wiki/Terra/terra-api/api-concepts/registries.md"}'),d={name:"wiki/Terra/terra-api/api-concepts/registries.md"};function c(n,e,p,k,g,y){const t=a("NolebaseGitContributors"),i=a("NolebaseGitChangelog");return l(),o("div",null,[e[0]||(e[0]=h('<h1 id="注册条目" tabindex="-1">注册条目 <a class="header-anchor" href="#注册条目" aria-label="Permalink to &quot;注册条目&quot;">​</a></h1> <p>注册条目是 Terra 中一个重要的概念。这使得 Terra、平台，以及其他附属能够检测你的附属对象是否存在，并鉴别它们。</p> <h2 id="什么是注册条目" tabindex="-1">什么是注册条目 <a class="header-anchor" href="#什么是注册条目" aria-label="Permalink to &quot;什么是注册条目&quot;">​</a></h2> <p>注册条目可以看作存有<em>注册项</em>与<em>条目</em>的映射表（维基百科称<a href="https://zh.wikipedia.org/wiki/%E5%85%B3%E8%81%94%E6%95%B0%E7%BB%84" target="_blank" rel="noreferrer">关联数组</a>）。注册条目注册指定类型的对象，并将它们分组归纳。注册项<em>单独鉴别</em>它们的条目，每个键只能对应一个条目。</p> <h2 id="注册条目用在什么地方" tabindex="-1">注册条目用在什么地方？ <a class="header-anchor" href="#注册条目用在什么地方" aria-label="Permalink to &quot;注册条目用在什么地方？&quot;">​</a></h2> <p>在 Terra 中，注册条目用于附属于配置包之间的物品引用。它们为附属与配置提供了一种创建与分享数据的方法，而无需额外编写兼容代码。</p> <h2 id="使用注册条目" tabindex="-1">使用注册条目 <a class="header-anchor" href="#使用注册条目" aria-label="Permalink to &quot;使用注册条目&quot;">​</a></h2> <p>大部分与 Terra API 的交互在某些时候也需要用到注册条目。</p> <h3 id="注册键" tabindex="-1">注册键 <a class="header-anchor" href="#注册键" aria-label="Permalink to &quot;注册键&quot;">​</a></h3> <p>注册条目通过 <a href="https://ci.codemc.io/job/PolyhedralDev/job/Terra/javadoc/com/dfsek/terra/api/registry/key/RegistryKey.html" target="_blank" rel="noreferrer">RegistryKey</a> 鉴别它们的值。注册键包含<em>命名空间</em>与<em>名称</em>。</p> <p>注册键可以通过 <code>RegistryKey#parse</code> 方法创建，解析 <code>命名空间:ID</code> 格式的注册键。它们也可以通过 <code>RegistryKey#of</code> 方法，带着命名空间与其 ID 创建。</p> <h4 id="命名空间" tabindex="-1">命名空间 <a class="header-anchor" href="#命名空间" aria-label="Permalink to &quot;命名空间&quot;">​</a></h4> <p>命名空间为对应注册值的提供者，通常是你的附属或配置包。带有命名空间的对象还实现了 <a href="https://ci.codemc.io/job/PolyhedralDev/job/Terra/javadoc/com/dfsek/terra/api/registry/key/Namespaced.html" target="_blank" rel="noreferrer">Namespaced</a> 接口。这个对象可以在命名空间中通过 <code>key(String identifier)</code> 方法创建注册键。</p> <h4 id="id-名称" tabindex="-1">ID/名称 <a class="header-anchor" href="#id-名称" aria-label="Permalink to &quot;ID/名称&quot;">​</a></h4> <p>ID 为值本身的名称。可能出现多个物品共用一个 ID 的情况，但它们可以通过各自的命名空间区分。能提供 ID 的物品同时实现了 <a href="https://ci.codemc.io/job/PolyhedralDev/job/Terra/javadoc/com/dfsek/terra/api/registry/key/StringIdentifiable.html" target="_blank" rel="noreferrer">StringIdentifiable</a>。</p> <h4 id="keyed" tabindex="-1">Keyed <a class="header-anchor" href="#keyed" aria-label="Permalink to &quot;Keyed&quot;">​</a></h4> <p><a href="https://ci.codemc.io/job/PolyhedralDev/job/Terra/javadoc/com/dfsek/terra/api/registry/key/Keyed.html" target="_blank" rel="noreferrer">Keyed</a> 接口由提供了自己的注册键的对象实现。</p> <h2 id="获取注册条目" tabindex="-1">获取注册条目 <a class="header-anchor" href="#获取注册条目" aria-label="Permalink to &quot;获取注册条目&quot;">​</a></h2> <p>注册条目可通过实现了 <a href="https://ci.codemc.io/job/PolyhedralDev/job/Terra/javadoc/com/dfsek/terra/api/registry/meta/RegistryHolder.html" target="_blank" rel="noreferrer">RegistryHolder</a> 的对象返回。一般情况下，这会是一个 <a href="https://ci.codemc.io/job/PolyhedralDev/job/Terra/javadoc/com/dfsek/terra/api/config/ConfigPack.html" target="_blank" rel="noreferrer">ConfigPack</a> 对象。<code>RegistryHolder</code> 定义了几个获取注册条目的方法。大部分情况下，你用到的是接受 <a href="https://docs.oracle.com/en/java/javase/21/docs/api/java.base/java/lang/Class.html" target="_blank" rel="noreferrer">Class</a> 或 <a href="https://terra.polydev.org/api/concepts/type-key.html" target="_blank" rel="noreferrer">TypeKey</a> 的方法。这里也有一个不额外检查的方法，接受原始的 <code>Type</code> 类型，但不建议使用它。</p> <p>先试试从配置包实例中获取 Sturcture 注册条目！</p> <div class="language-Java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pack.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getRegistry</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(Structure.class); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 返回持有 Structure 实例的单独注册条目。</span></span></code></pre></div><h2 id="获取可写入条目" tabindex="-1">获取可写入条目 <a class="header-anchor" href="#获取可写入条目" aria-label="Permalink to &quot;获取可写入条目&quot;">​</a></h2> <p>上个示例中获取的注册条目是<em>只读</em>的，它只适合<em>获取</em>信息。但你肯定需要频繁注册自己的对象，因此我们有 <a href="https://ci.codemc.io/job/PolyhedralDev/job/Terra/javadoc/com/dfsek/terra/api/registry/CheckedRegistry.html" target="_blank" rel="noreferrer">CheckedRegistry</a>，它获取的方式与 <a href="https://ci.codemc.io/job/PolyhedralDev/job/Terra/javadoc/com/dfsek/terra/api/registry/CheckedRegistry.html" target="_blank" rel="noreferrer">Registry</a> 从 <a href="https://ci.codemc.io/job/PolyhedralDev/job/Terra/javadoc/com/dfsek/terra/api/registry/meta/RegistryHolder.html" target="_blank" rel="noreferrer">RegistryHolder</a> 处获取类似，因此也可以从 <a href="https://ci.codemc.io/job/PolyhedralDev/job/Terra/javadoc/com/dfsek/terra/api/registry/meta/CheckedRegistryHolder.html" target="_blank" rel="noreferrer">CheckedRegistryHolder</a> 处返回。</p> <p>来试试看注册点东西吧！</p> <div class="language-Java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pack.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getCheckedRegistry</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(Structure.class).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">register</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(myAddon.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">key</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my_structure&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> MyStructure</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 注册 MyStructure 的新示例，注册键为“my_addon:my_structure”。</span></span></code></pre></div><h3 id="创建注册条目" tabindex="-1">创建注册条目 <a class="header-anchor" href="#创建注册条目" aria-label="Permalink to &quot;创建注册条目&quot;">​</a></h3> <p>有时，你可能需要为自己的对象创建一个注册条目。实现了 <a href="https://ci.codemc.io/job/PolyhedralDev/job/Terra/javadoc/com/dfsek/terra/api/registry/meta/RegistryProvider.html" target="_blank" rel="noreferrer">RegistryProvider</a> 的对象可以通过 <code>#getOrCreateRegistry</code> 方法创建 <a href="https://ci.codemc.io/job/PolyhedralDev/job/Terra/javadoc/com/dfsek/terra/api/registry/CheckedRegistry.html" target="_blank" rel="noreferrer">CheckedRegistry</a> 实例。</p> ',52)),r(t),r(i)])}const f=s(d,[["render",c]]);export{b as __pageData,f as default};
